import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const read=p=>readFileSync(new URL('../'+p,import.meta.url),'utf8');
const css=read('studio-sidebar-modern.css'),html=read('index.php');
const sw=read('sw.js'),script=read('script.js');
const start=css.indexOf('/* Mobile polish 2386');
assert.ok(start>0);
const patch=css.slice(start);
assert.match(patch,/@media \(max-width:768px\)/);
assert.match(patch,/--mobile-gutter:clamp\(12px,3\.8vw,18px\)/);
assert.match(patch,/\.showcase-nav-btn \{\s*display:flex!important;flex-direction:row!important/);
assert.match(patch,/height:56px!important/);
assert.match(patch,/\.showcase-nav-btn > span \{\s*display:block!important/);
assert.match(patch,/\.vision-topbar \{/);
assert.match(patch,/\.vision-mini-player \{/);
assert.match(patch,/\.vision-bottom-nav \{/);
assert.match(patch,/\.vision-quick-grid,\.vision-ui \.showcase-curation-list \{/);
assert.match(patch,/max-width:360px/);
assert.match(patch,/max-height:650px/);
assert.match(patch,/\.vision-ui\.vision-player-expanded \.vision-bottom-nav/);
assert.match(html,/studio-sidebar-modern\.css\?v=12/);
assert.match(sw,/studio-sidebar-modern\.css\?v=12/);
assert.match(html,/script\.js\?v=2393/);
assert.match(sw,/dagstudio-player-shell-v2411/);
assert.match(script,/WEB_BUILD_LABEL = '2393'/);
const uncomments=css.replace(/\/\*[\s\S]*?\*\//g,'');
assert.equal((uncomments.match(/\{/g)||[]).length,(uncomments.match(/\}/g)||[]).length,'Balanced layout blocks');
const isolation=css.slice(css.indexOf('/* Mobile player/list isolation 2394'));
assert.ok(isolation.startsWith('/* Mobile player/list isolation 2394'));
assert.match(isolation,/\.vision-player-expanded\.showcase-mobile-list:not\(\.showcase-wave-only\)>\.right-col/);
assert.match(isolation,/\.right-col \{\s*display:none!important/);
assert.match(isolation,/height:100dvh!important/);
assert.match(isolation,/overflow-y:auto!important/);
assert.match(isolation,/\.right-col\.showcase-list \.playlist-area/);
assert.match(isolation,/max-width:430px/);
assert.match(isolation,/max-height:700px/);
console.log('MOBILE_PHONE_LAYOUT_ALIGNED_SAFE_AREA_CARDS_DRAWER_PLAYER_OK');
